import { workflow, step } from "@executioncontrolprotocol/core"

export default workflow("Validate then echo")
  .run([
    step("@executioncontrolprotocol/test.validate", "Validate").id("validate").with({ payload: { ok: true } }).as("validated"),
    step("@executioncontrolprotocol/test.echo", "Echo").id("echo").with({ value: "hello" }).as("echo"),
  ])

import { workflow, step } from "@executioncontrolprotocol/core"

export default workflow("Echo translate")
  .run([
    step("@executioncontrolprotocol/test.echo", "Echo").id("echo").with({ value: "hello" }).as("echo"),
    step("@executioncontrolprotocol/test.translate", "Translate").id("translate").with({ text: "hello", targetLang: "es" }).as("translated"),
  ])

import { workflow, step, ref } from "@executioncontrolprotocol/core"

export default workflow("Chrome generate from prompt")
  .id("chrome-generate-from-prompt")
  .accepts({ type: "object", properties: { prompt: { type: "string" } }, required: ["prompt"] })
  .returns({
    type: "object",
    properties: {
      response: {
        type: "object",
        properties: { text: { type: "string" } },
        required: ["text"],
      },
    },
    required: ["response"],
  })
  .run([
    step("@executioncontrolprotocol/chrome-ai.generate", "Generate")
      .id("generate")
      .with({ prompt: ref("prompt") })
      .as("response"),
  ])
